function releaseEditor(e,cancel=false){editorPointers.delete(e.pointerId);if(!builderDrag)return;if(builderDrag.pinch){if(!editorPointers.size)builderDrag=null;return;}const d=builderDrag;builderDrag=null;editorPointers.clear();if(cancel&&d.paintBefore){draft=d.paintBefore;builderHistory.length=d.historyAt;}if(!cancel){if(d.choice&&!d.moved)chooseEntry98(d.x,d.y);else if(d.port&&preview98){const[dx,dy]=B.dirs[d.direction];appendNode(dx,dy,d.parent);}else if(d.node!==undefined&&!d.moved)selectNode98(d.node);}if(cancel||d.port){preview98=null;paintPreview98();}if(draft)drawBuilder();}
