// The preview is local until Confirm; the same v3 battle record and LAN commit are reused.
let weaponPreview103=null;
shelfOpen=options.trajectories===true;mode=shelfOpen?'weapon':'free';
function tierPattern(w,tier){const map=new Map();return{...w,nodes:w.nodes.filter((n,i)=>{if(n.tier>tier||i&&!map.has(n.parent))return false;map.set(i,map.size);return true;}).map((n,i)=>({...n,parent:i?map.get(n.parent):-1}))};}
const baseShow103=show,baseChrome103=updateChrome,baseBack103=back,baseFocus103=focusEnemy,baseCancel103=cancelProposal;
show=function(next='field'){
 if(pending)return;cancelWeapon103();cancelCurrentGesture();if(page==='editor'&&next!=='editor')draft=null;
 page=next;for(const n of ['field','attacks','editor'])$(n).hidden=n!==next;
 $('tracks-entry').setAttribute('aria-pressed',shelfOpen);$('tracks-entry').textContent='攻击轨迹';
 if(next==='field')requestAnimationFrame(()=>{layoutScene();updateChrome();});
 if(next==='attacks')renderAttacks();
 if(!reducedMotion)$(next).animate([{opacity:.3,transform:'translateY(6px)'},{opacity:1,transform:'none'}],{duration:190,easing:'cubic-bezier(.2,.8,.2,1)'});
};
updateChrome=function(){baseChrome103();$('tracks-entry').disabled=pending;$('tracks-entry').setAttribute('aria-pressed',shelfOpen);$('field').classList.toggle('tracks-open',shelfOpen);$('track-dock').hidden=!shelfOpen||page!=='field'||!state.foes.length;};
back=function(){if(!$('modal').hidden){baseBack103();return;}if(page==='editor'&&draft){const original=state.attacks.find(w=>w.id===draft.id),next={...draft,name:$('attack-name').value.trim()||draft.name};if(JSON.stringify(next)!==JSON.stringify(original)){modal('离开轨迹编辑','<p>当前轨迹修改还未保存。</p><div class="confirm-actions"><button id="keep-draft">继续编辑</button><button id="leave-draft" class="primary">放弃修改</button></div>',()=>{$('keep-draft').onclick=close;$('leave-draft').onclick=()=>{close();show('attacks');};});return;}show('attacks');return;}if(page!=='field'){show('field');return;}if(weaponPreview103){cancelWeapon103();return;}if(shelfOpen){toggleTracks103(false);return;}baseBack103();};
focusEnemy=function(i){cancelWeapon103();baseFocus103(i);};
function cancelWeapon103(){weaponPreview103=null;$('attack-forecast').hidden=true;baseCancel103();}
function toggleTracks103(open=!shelfOpen){cancelWeapon103();shelfOpen=open;options.trajectories=open;optionsSave();mode=open?'weapon':'free';if(scene!=='focus'&&state.foes.length)baseFocus103(state.selected);renderTrackDock103();updateChrome();requestAnimationFrame(layoutScene);}
const rememberedTrackTiers104=new Map(),trackTierNames104=['Ⅰ档','Ⅱ档','Ⅲ档'];
function selectTrack103(id,tier){cancelWeapon103();mode='weapon';state.attack=id;state.tier=tier;rememberedTrackTiers104.set(id,tier);renderTrackDock103();if(!shelfOpen)toggleTracks103(true);}
function chosenTrackTier104(w){const tiers=[...new Set(w.nodes.map(n=>n.tier))].sort(),prior=w.id===state.attack?state.tier:rememberedTrackTiers104.get(w.id);return tiers.includes(prior)?prior:tiers[0];}
function chooseTrack104(id){
 const w=state.attacks.find(w=>w.id===id);if(!w)return;const tiers=[...new Set(w.nodes.map(n=>n.tier))].sort();if(tiers.length===1){selectTrack103(id,tiers[0]);return;}
 const selected=chosenTrackTier104(w);modal('选择轨迹档位',`<div class="track-tier-choices">${tiers.map(t=>`<button data-choose-track-tier="${t}" aria-pressed="${t===selected}">${diagram(tierPattern(w,t))}<span>${trackTierNames104[t]}</span></button>`).join('')}</div>`,()=>{document.querySelectorAll('[data-choose-track-tier]').forEach(b=>b.onclick=()=>{close();selectTrack103(id,+b.dataset.chooseTrackTier);});});
}
function renderTrackDock103(){
 $('track-tray').innerHTML=state.attacks.map(w=>{const tiers=[...new Set(w.nodes.map(n=>n.tier))].sort(),t=chosenTrackTier104(w);return `<button class="track-chip ${w.id===state.attack?'selected':''}" data-track="${E(w.id)}" data-track-tier="${t}" aria-label="${E(w.name)}，${trackTierNames104[t]}，${tiers.length>1?'点击选档，':''}选择后点击命中点预览">${diagram(tierPattern(w,t))}<span>${E(w.name)}${tiers.length>1?`<small>${trackTierNames104[t]} ⌄</small>`:''}</span></button>`;}).join('');
}
function paintWeapon103(x,y){
 const f=current();if(!f)return;const hit=nearestPoint({x,y},pointData(f.id,true));
 if(!hit){weaponPreview103=null;baseCancel103();$('forecast-copy').textContent='点击一个命中点';$('confirm-track').disabled=true;return;}
 if(weaponPreview103?.id===f.id&&weaponPreview103.index===hit.i)return;
 const t=template(f),result=B.preview(t,f,attack(),state.tier,hit.i,spiritOverride===f.id);weaponPreview103={id:f.id,index:hit.i,result,base:B.signature(f),attack:JSON.stringify(attack()),tier:state.tier};
 showProposal(result,f.id);$('attack-forecast').hidden=false;$('confirm-track').disabled=!result.valid;
 $('forecast-copy').textContent=result.message||(result.valid?[result.wounds?result.wounds+'处命中':'',result.armor?result.armor+'处破甲':'',result.weak.length?result.weak.length+'处弱点':''].filter(Boolean).join(' · '):'此点不符合轨迹起点，请换一个命中点');
}
$('track-tray').addEventListener('click',e=>{const b=e.target.closest('[data-track]');if(!b||pending)return;cancelCurrentGesture();unlockAudio();chooseTrack104(b.dataset.track);});
$('stage').addEventListener('pointerdown',e=>{
 if(mode!=='weapon'||!shelfOpen||scene!=='focus'||e.target.closest('button,input'))return;
 const hit=current()?nearestPoint({x:e.clientX,y:e.clientY},pointData(current().id)):null;if(hit&&current().marks[hit.i]===2)return;
 e.stopImmediatePropagation();e.preventDefault();cancelCurrentGesture();paintWeapon103(e.clientX,e.clientY);
},true);
$('confirm-track').onclick=async()=>{
 const p=weaponPreview103,f=current();if(!p||!p.result.valid||pending)return;
 if(f?.id!==p.id||B.signature(f)!==p.base||JSON.stringify(attack())!==p.attack){cancelWeapon103();toast('战斗记录已变化，请重新预览');return;}
 const result=B.preview(template(f),f,attack(),p.tier,p.index,spiritOverride===f.id);if(!result.valid){cancelWeapon103();return;}
 if(await mutate(s=>{const target=s.foes.find(x=>x.id===p.id);if(!target)throw Error('敌人已被移出');B.record(target,result.marks,result.effects);},true)){
  if(spiritOverride===f.id)spiritOverride=null;
  cancelWeapon103();for(const e of result.events){strike(p.id,e);playCue('hit',e);}for(const c of result.criticals){flashCritical(p.id,c,result.paths);playCue('critical');}reconcileCards();haptic('select');reportAttack(template(f),result);
 }
};
$('cancel-track').onclick=cancelWeapon103;
$('tracks-entry').onclick=()=>toggleTracks103();
$('edit-tracks').onclick=()=>show('attacks');$('close-tracks').onclick=()=>toggleTracks103(false);$('new-attack').onclick=()=>edit(B.blankAttack());$('save-attack').onclick=saveAttack;
$('builder-undo').onclick=undoEditor98;$('delete-node').onclick=removeNode;$('builder-fit').onclick=()=>fitEditor();$('aimed').onclick=()=>{entryBefore={record:B.clone(draft),active:node,choosing:choosingEntry98};choosingEntry98=!choosingEntry98;drawBuilder();};
