document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.use){show('field');toggleTracks103(true);chooseTrack104(b.dataset.use);}if(b.dataset.edit)edit(state.attacks.find(w=>w.id===b.dataset.edit));if(b.dataset.deleteAttack){const id=b.dataset.deleteAttack;modal('删除轨迹','<p>删除这条自定义轨迹？</p><div class="confirm-actions"><button id="keep-attack">保留</button><button id="remove-attack" class="primary">删除</button></div>',()=>{$('keep-attack').onclick=close;$('remove-attack').onclick=async()=>{if(await mutate(s=>{if(s.attacks.length<=1)throw Error('请至少保留一条轨迹');s.attacks=s.attacks.filter(w=>w.id!==id);if(s.attack===id)s.attack=s.attacks[0].id;})){close();renderAttacks();renderTrackDock103();}};});}});
document.addEventListener('visibilitychange',()=>{if(document.hidden)cancelWeapon103();});
