const baseRemote103=applyRemote;
applyRemote=function(data){const prior=current(),before=prior&&B.signature(prior),id=prior?.id;const selectedAttack=JSON.stringify(attack());baseRemote103(data);const next=current();if(next?.id!==id||(next&&B.signature(next))!==before||JSON.stringify(attack())!==selectedAttack)cancelWeapon103();};

function back(){if(!$('modal').hidden){modalBack();return;}if(scene==='overview'&&state.foes.length){focusEnemy(state.selected);return;}if(window.AndroidCombat)AndroidCombat.close();else if(location.pathname.startsWith('/combat'))location.href='/';}
async function refreshBrowserSession(){if(window.AndroidCombat||closed)return;try{const response=await fetch('/api/combat',{cache:'no-store'});if(!response.ok){if(response.status===401&&location.pathname.startsWith('/combat/'))location.replace('/');return;}const envelope=await response.json();if(envelope.theme)for(const[key,value]of Object.entries({paper:envelope.theme.paper,ink:envelope.theme.ink,muted:envelope.theme.muted,line:envelope.theme.line,pine:envelope.theme['accent-text'],solid:envelope.theme.accent,sage:envelope.theme.tint,card:envelope.theme.tint,accent:envelope.theme.tint}))if(typeof value==='string'&&/^#[a-f0-9]{6}$/i.test(value))document.documentElement.style.setProperty('--'+key,value);envelope.browser=true;onSession(envelope);}catch{if(session.browser&&session.connected){session.connected=false;renderSession();}}}
$('manage').querySelector('span').innerHTML=icon('chevron');
for(const[id,key]of Object.entries({back:'back',settings:'settings',add:'plus','zoom-in':'plus','zoom-out':'minus',fit:'fit',undo:'undo','show-overview':'grid','modal-back':'back','close-modal':'close'}))$(id).innerHTML=icon(key);
document.addEventListener('pointerdown',unlockAudio,{passive:true});document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.enemy)chooseEnemy(b.dataset.enemy);if(b.dataset.focus!==undefined)focusEnemy(+b.dataset.focus);});
$('empty-entry').onsubmit=e=>{e.preventDefault();findEnemy($('empty-code').value,'entry-error');};$('back').onclick=back;$('settings').onclick=battleSettings;$('enemy-ai').onclick=()=>enemyAI();$('add').onclick=enemyEntry;$('manage').onclick=roster;$('undo').onclick=undoEnemy;$('show-overview').onclick=()=>scene==='overview'?focusEnemy(state.selected):overviewScene();$('zoom-in').onclick=()=>zoom(1.24);$('zoom-out').onclick=()=>zoom(1/1.24);$('fit').onclick=resetCamera;$('close-modal').onclick=close;$('modal-back').onclick=modalBack;document.querySelector('.scrim').onclick=close;
$('session').onclick=()=>modal('局域网战斗',`<p>${session.connected?'当前与地图共用同一个局域网房间，已确认的受伤和护甲状态会同步给队友。':'在地图联机设置中创建或加入房间后，战斗会使用同一个房间。'}</p>`);
window.CombatApp={snapshot:()=>B.clone(state),templates:D.templates,back:()=>{const nested=!$('modal').hidden||scene==='overview'||page!=='field'||shelfOpen||!!weaponPreview103;back();return nested;},commitResult,onSession,view:()=>({page,scene,mode:'slice',camera:{...camera},options:{...options},busy:pending||draining,fx:!!fxScenes.length,phase:gesture?.kind==='draw'?'slicing':'ready',revision:session.revision,audio:{state:audioContext?.state||'idle',cues:audioCount},queue:actionQueue.length,motion:{...motionStats}})};
function stop(){closed=true;cancelCurrentGesture();cancelEffects();cancelAnimationFrame(sceneFrame);sceneFrame=0;cancelAnimationFrame(bladeFrame);clearTimeout(summaryTimer);clearInterval(roomPoll);audioContext?.suspend();for(const task of requests.values()){clearTimeout(task.timeout);task.reject(Error('页面已关闭'));}requests.clear();}
window.addEventListener('pagehide',stop);document.addEventListener('visibilitychange',()=>{if(document.hidden){cancelCurrentGesture();cancelProposal();audioContext?.suspend();}else{closed=false;sceneFrame=0;layoutScene();refreshBrowserSession();}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();back();}});
if(state.foes.length)scene='focus';renderTrackDock103();reconcileCards();renderSession();['fx/printed-points.webp','fx/wound.png'].forEach(warmSprite);if(window.AndroidCombat?.session97){try{onSession(JSON.parse(AndroidCombat.session97()));}catch{toast('联机状态暂未读取');}}else{refreshBrowserSession();roomPoll=setInterval(refreshBrowserSession,900);}
